"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["22631"],{3362(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.opcional_que_alimenta_regra","status":422,"titulo":"Campo que alimenta deriva\xe7\xe3o, agregado ou nega\xe7\xe3o precisa ser obrigat\xf3rio sempre que exibido"},"descricao":{"codigo":"uniplus.item_formulario.opcional_que_alimenta_regra","requisitos":["UNI-REQ-0074"],"oQueAconteceu":["O campo opcional deixado em branco, com a etapa conclu\xedda, resolve sem valor, e todo operador sobre ele d\xe1 falso, inclusive `DIFERENTE` e `NAO_EM` (UNI-REQ-0074). Por isso o campo cujo fato \xe9 depend\xeancia de uma deriva\xe7\xe3o, ou \xe9 citado por `DIFERENTE` ou `NAO_EM` em qualquer regra, diretamente ou por um derivado, tem de ser obrigat\xf3rio sempre que exibido: a obrigatoriedade `NUNCA` ou `QUANDO` \xe9 recusada. A API aplica a mesma regra a mais dois casos que o requisito n\xe3o declara: o campo com impedimento, que em branco nunca impediria, e o campo de um grupo repet\xedvel que participa de um resumo de grupo, caso em que o grupo e o campo precisam ser obrigat\xf3rios sempre. A mensagem diz o caso:","A mensagem identifica o campo `{fato\\\\}` ou o grupo `{c\xf3digo\\\\}` que precisa ser obrigat\xf3rio sempre que exibido.","A recusa \xe9 \xfanica, a do primeiro campo ou grupo que contraria a regra, na ordem do formul\xe1rio, e vem sem `field` no processo e com `field` igual a `conteudo` no modelo de formul\xe1rio. No modelo, ela s\xf3 sai quando a forma de todo o conte\xfado, a estrutura das se\xe7\xf5es e o grafo de coleta n\xe3o t\xeam recusa, e vem depois delas. No processo, a publica\xe7\xe3o inicial e a retifica\xe7\xe3o em ato \xfanico conferem a configura\xe7\xe3o inteira, porque a regra que faz o campo alimentar uma deriva\xe7\xe3o ou uma nega\xe7\xe3o pode ser acrescentada depois de o campo ser gravado; o caso do grupo \xe9 conferido mais adiante, com os fatos citados pelos gatilhos dos documentos exigidos. A grava\xe7\xe3o dos itens do formul\xe1rio n\xe3o faz esta confer\xeancia. Nada \xe9 gravado. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Torne o campo, e o grupo quando for o caso, obrigat\xf3rio sempre que exibido (obrigatoriedade `SEMPRE`, sem predicado), ou retire a regra que usa o campo na deriva\xe7\xe3o, no resumo de grupo, na nega\xe7\xe3o ou no impedimento. Em processo j\xe1 publicado, a corre\xe7\xe3o \xe9 feita numa retifica\xe7\xe3o."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);